    @inline(__always)
    private func checkMultiplySubtractingAddingConstantAB(_ aValue: Lane, _ bValue: Lane) {
        let mismatches = Mismatches(
            "multiplySubtractingAdding with a repeating \(hex(aValue)), b repeating \(hex(bValue))"
        )
        let cInputs = Inputs.vectors(H.self, seed: 0x3EB4_C987_D259_8984)
        mismatches.check(
            H.repeating(aValue),
            H(raw: HighwayReference.repeatingI64(aValue)),
            "repeating"
        )
        mismatches.check(
            H.repeating(bValue),
            H(raw: HighwayReference.repeatingI64(bValue)),
            "repeating"
        )
        for c in cInputs {
            mismatches.check(
                H.multiplySubtractingAdding(H.repeating(aValue), H.repeating(bValue), c),
                H(
                    raw: HighwayReference.multiplySubtractingAddingI64(
                        H.repeating(aValue).raw,
                        H.repeating(bValue).raw,
                        c.raw
                    )
                ),
                "c: \(describe(c))"
            )
        }
        mismatches.record()
    }

